/**
 * G7-L — Normalize + route intent (orchestration only).
 * No SQL. No Supabase. No Core business rules.
 * Credentials ONLY via $env (never hardcode).
 */
const input = $json || {};
const scenario = String($env.SENTINELA_G7L_SCENARIO || input.scenario || 'identify_resident');
const externalMessageId = String(
  input.external_message_id || $env.SENTINELA_G7L_EXTERNAL_MESSAGE_ID || 'g7l-pilot-msg-001'
);
const requestId = String(input.request_id || `req_g7l_${externalMessageId}`.replace(/[^A-Za-z0-9_.:-]/g, '_').slice(0, 128));
const baseUrl = String($env.SENTINELA_PILOT_BASE || 'http://127.0.0.1:3099');
const clientId = String($env.SENTINELA_N8N_CLIENT_ID || $env.SENTINELA_HARNESS_CLIENT_ID || 'n8n-pilot-test');

function idemKey(intent) {
  // STABLE — same external message → same key on retry (never Date.now())
  return `n8n:${clientId}:${intent}:${externalMessageId}:v1`.slice(0, 128);
}

const routes = {
  identify_resident: {
    intent: 'IDENTIFY_RESIDENT',
    method: 'GET',
    path: '/api/v1/residents/identify?name=Maria%20Pilot&unit=101',
    auth: true,
    classification: 'READ'
  },
  create_package: {
    intent: 'CREATE_PACKAGE',
    method: 'POST',
    path: '/api/v1/operations/packages',
    auth: true,
    classification: 'WRITE',
    body: {
      recipient: 'G7-L-N8N-TEST',
      unit: '101',
      type: 'caixa',
      input_type: 'text',
      text: 'pilot package G7-L',
      metadata: { source: 'n8n', gate: 'G7-L' }
    },
    idempotencyKey: idemKey('CREATE_PACKAGE')
  },
  health: {
    intent: 'HEALTH',
    method: 'GET',
    path: '/api/v1/health',
    auth: false,
    classification: 'READ'
  },
  unknown: {
    intent: 'UNKNOWN',
    method: null,
    path: null,
    auth: false,
    not_supported: true,
    decision: 'NOT_SUPPORTED'
  }
};

const cfg = routes[scenario] || routes.identify_resident;
if (cfg.not_supported) {
  return [{ json: { ok: false, decision: 'NOT_SUPPORTED', intent: cfg.intent, whatsapp: 0, sql: 0 } }];
}

return [{
  json: {
    gate: 'G7-L',
    scenario,
    intent: cfg.intent,
    method: cfg.method,
    path: cfg.path,
    body: cfg.body || null,
    idempotencyKey: cfg.idempotencyKey || '',
    auth: cfg.auth !== false,
    classification: cfg.classification,
    baseUrl,
    requestId,
    external_message_id: externalMessageId,
    whatsapp: 0,
    postgres_node: 0
  }
}];

const method = String($json.method || 'GET').toUpperCase();
const pathWithQuery = String($json.path || '/api/v1/health');
const bodyObj = $json.body;
const body =
  bodyObj === undefined || bodyObj === null
    ? ''
    : typeof bodyObj === 'string'
      ? bodyObj
      : JSON.stringify(bodyObj);
const idempotencyKey = String($json.idempotencyKey || '');
const baseUrl = String($json.baseUrl || $env.SENTINELA_PILOT_BASE || 'http://127.0.0.1:3099');
const requestId = String($json.requestId || `req_g7l_${Date.now()}`);

if ($json.auth === false) {
  return [{
    json: {
      ...$json,
      method,
      path: pathWithQuery,
      body,
      url: `${baseUrl}${pathWithQuery}`,
      headers: { 'X-Request-Id': requestId },
      meta: { canonical_version: 'v1', auth: false }
    }
  }];
}

const nodeCrypto = require('crypto');
const secret = $env.SENTINELA_N8N_SECRET || $env.SENTINELA_HARNESS_SECRET;
const clientId = $env.SENTINELA_N8N_CLIENT_ID || $env.SENTINELA_HARNESS_CLIENT_ID;
const org = $env.SENTINELA_N8N_ORGANIZATION_ID || $env.SENTINELA_HARNESS_ORG;
const condo = $env.SENTINELA_N8N_CONDOMINIUM_ID || $env.SENTINELA_HARNESS_CONDO;

if (!secret || !clientId || !org || !condo) {
  throw new Error('Missing Sentinela n8n credential env vars');
}

const timestamp = String(Math.floor(Date.now() / 1000));
const bodySha = nodeCrypto.createHash('sha256').update(body).digest('hex');
const canonical = ['v1', timestamp, method, pathWithQuery, bodySha, org, condo, idempotencyKey].join('\n');
const signature = nodeCrypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');

return [{
  json: {
    ...$json,
    method,
    path: pathWithQuery,
    body,
    url: `${baseUrl}${pathWithQuery}`,
    headers: {
      'X-Sentinela-Client-Id': clientId,
      'X-Sentinela-Timestamp': timestamp,
      'X-Sentinela-Signature': signature,
      'X-Organization-Id': org,
      'X-Condominium-Id': condo,
      'X-Request-Id': requestId,
      ...(idempotencyKey ? { 'Idempotency-Key': idempotencyKey } : {}),
      ...(body ? { 'Content-Type': 'application/json' } : {})
    },
    meta: { canonical_version: 'v1', body_sha256: bodySha }
  }
}];

/**
 * Treat API envelope — never log secrets / confirmation tokens / HMAC.
 */
const prev = $('Generate HMAC').item.json;
const body = $json;
const requestId = body.request_id || prev.requestId || null;
const success = body.success === true;
const errorCode = body.error && body.error.code ? body.error.code : null;
const httpHint = body.error && body.error.details ? body.error.details : null;
const core = body.data && body.data.core_executed;

const NO_AUTO_RETRY = new Set([
  'INVALID_REQUEST','INVALID_TIME_RANGE','FORBIDDEN','TENANT_MISMATCH',
  'TENANT_REQUIRED','TENANT_NOT_FOUND','UNAUTHENTICATED','INVALID_SIGNATURE',
  'TIMESTAMP_EXPIRED','IDEMPOTENCY_FINGERPRINT_MISMATCH','DUPLICATE_REQUEST',
  'CONFIRMATION_REQUIRED','CONFIRMATION_INVALID','CONFIRMATION_EXPIRED',
  'CONFIRMATION_ALREADY_CONSUMED','NEEDS_CONFIRMATION','RESOURCE_NOT_FOUND'
]);

let retry_action = 'no_retry';
if (!success) {
  if (errorCode === 'CONFIRMATION_REQUIRED' || errorCode === 'NEEDS_CONFIRMATION') retry_action = 'confirmation_flow';
  else if (errorCode === 'INVALID_SIGNATURE' || errorCode === 'TIMESTAMP_EXPIRED') retry_action = 're_sign';
  else if (errorCode === 'CONFLICT') retry_action = 'retry_after_change';
  else if (errorCode === 'INTERNAL_ERROR' || errorCode === 'IDEMPOTENCY_STORE_UNAVAILABLE') retry_action = 'retry_same_key';
  else if (NO_AUTO_RETRY.has(errorCode)) retry_action = 'no_retry';
}

return [{ json: {
  gate: 'G7-L',
  ok: success,
  request_id: requestId,
  idempotency_key: prev.idempotencyKey || null,
  intent: prev.intent,
  operation: body.operation || (body.data && body.data.operation) || null,
  success,
  error_code: errorCode,
  core_executed: core ?? false,
  retry_action,
  user_safe: success === true && prev.classification === 'READ',
  whatsapp: 0,
  sql_access: 0,
  event_store_direct: 0,
  note: 'Do not log headers, signature, secret, or confirmation_token'
}}];

return [{ json: {
  pilot: 'G7-L',
  workflow_active: false,
  result: $json,
  whatsapp: 0,
  n8n_prod: 0,
  postgres_node: 0,
  supabase_direct: 0
}}];
